#pragma once

#include "eventProto.capnp.h" // Generated by `capnp compile`
#include <capnp/ez-rpc.h>
#include <kj/async-io.h>
#include <iostream>
#include <map>
#include <mutex>

#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>
#include <cerrno>
#include <cstring>
#include <sys/ioctl.h>
#include <unistd.h>

#define CURSOR_UP(N) "\033[" #N "A"
#define ERASE_LINE "\033[K"

using namespace std;

std::mutex g_state_mutex;

class syncState
{
public:
    uint16_t procId;
    uint16_t maxId;
    uint64_t time;
    string filename;
    string op;
    double proc;
};

class StateSynchronizerImpl final : public StateSynchronizer::Server
{
public:
    StateSynchronizerImpl()
    {
        printFuture = async(std::launch::async, [this]()
                            {
            printState = true;

            terminalSize = getTerminalSize();
            
            printHeaderDashboard();
                                
            while(printState){
                if((getCrtTime() - updateTime) > 1e9){

                    std::lock_guard<std::mutex> lock(g_state_mutex);
                    printStatusDashboard();

                    dumpToFile();

                    updateTime = getCrtTime();
                }
            } });
    }

    ~StateSynchronizerImpl()
    {
        printState = false;

        printFuture.get();
    }

    // This is the implementation of the `reportState` function.
    kj::Promise<void> reportState(ReportStateContext context) override
    {

        {
            std::lock_guard<std::mutex> lock(g_state_mutex);

            syncState state;

            state.procId = context.getParams().getState().getProcId();
            state.maxId = context.getParams().getState().getMaxId();
            state.op = context.getParams().getState().getOp();
            state.proc = context.getParams().getState().getProc();
            state.time = context.getParams().getState().getTime();
            state.filename = context.getParams().getState().getFilename();

            stateMap[state.procId] = state;
        }

        // 3. Set the return value and send the reply
        context.getResults().setAcknowledged(true);

        return kj::READY_NOW; // We are done.
    }

    pair<int, int>
    getTerminalSize()
    {
        struct winsize w;
        ioctl(STDOUT_FILENO, TIOCGWINSZ, &w);
        return {w.ws_col, w.ws_row};
    }

    bool isEven(int n)
    {
        if (n % 2 == 0)
        {
            return true;
        }
        return false;
    }

    string getFormatedString(string value, int size, bool end = false, char cPad = ' ')
    {
        if (value.size() > size)
        {
            if (!end)
            {
                value += "|";
            }

            return value;
        }

        int padding = size - value.size();

        if (isEven(padding))
        {
            auto pad = string(padding / 2, cPad);

            value = pad + value + pad;
        }
        else
        {
            auto fPad = string(padding / 2, cPad);
            auto bPad = string(padding / 2 + 1, cPad);
            value = fPad + value + bPad;
        }

        if (!end)
        {
            value += "|";
        }

        return value;
    }

    string convertTime(uint64_t time)
    {

        int seconds = time % 60;
        int minutes = time / 60;

        string sSeconds = "0" + to_string(seconds);
        sSeconds = sSeconds.substr(sSeconds.size() - 2, 2);

        string sMinutes = "0" + to_string(minutes);
        sMinutes = sMinutes.substr(sMinutes.size() - 2, 2);

        string tTime = sMinutes + ":" + sSeconds;

        return tTime;
    }

    string getMoveCommand(int n)
    {
        return "\033[" + to_string(n) + "A";
    }

    string roundDouble(double value, string end = "%", size_t decimals = 2)
    {
        string sValue = to_string(value);

        auto pos = sValue.find_first_of(".") + 1;

        sValue = sValue.substr(0, pos + decimals);

        sValue += end;

        if (pos == 2)
        {
            sValue = "0" + sValue;
        }
        else if (pos == 4)
        {
            sValue = sValue + " ";
        }

        return sValue;
    }

    void dumpToFile()
    {
        ofstream outFile("builderStatus.txt");

        int tSize = getMaxWidth();

        outFile << getFormatedString(" Builder status ", tSize, true, '-') << endl;
        outFile << getFormatedString("#id", printSpaces["id"])
                << getFormatedString("#time", printSpaces["time"])
                << getFormatedString("#file", printSpaces["file"])
                << getFormatedString("#op", printSpaces["op"])
                << getFormatedString("#status", printSpaces["status"], true)
                << endl;

        outFile << string(tSize, '-') << endl;

        for (const auto &p : stateMap)
        {
            string id = to_string(p.second.procId) + "/" + to_string(p.second.maxId);
            string time = convertTime(p.second.time);
            string filename = p.second.filename;
            string op = p.second.op;
            string proc = roundDouble(p.second.proc);

            if (p.second.op == "done")
            {
                proc = "-";
            }

            outFile << getFormatedString(id, printSpaces["id"])
                    << getFormatedString(time, printSpaces["time"])
                    << getFormatedString(filename, printSpaces["file"])
                    << getFormatedString(op, printSpaces["op"])
                    << getFormatedString(proc, printSpaces["status"], true)
                    << endl;
        }
        outFile.close();
    }

    void printStatusDashboard()
    {
        if (stateMap.size())
        {
            // terminal was changed reprint header
            auto tempSize = getTerminalSize();

            if (tempSize != terminalSize)
            {

                if (tempSize.first <= getMaxWidth() || tempSize.second <= stateMap.size())
                {

                    cout << endl;
                    printHeaderDashboard();
                    firstPass = true;
                }

                terminalSize = tempSize;
            }

            if (firstPass)
            {
                firstPass = false;
            }
            else
            {
                std::cout << getMoveCommand(getLastRowCount());
            }

            int cps = 0;
            int writeLines = 0;
            int mapSize = stateMap.size();

            for (const auto &p : stateMap)
            {
                if ((mapSize - cps + 1) > tempSize.second)
                {
                    cps++;
                    continue;
                }

                string id = to_string(p.second.procId) + "/" + to_string(p.second.maxId);
                string time = convertTime(p.second.time);
                string filename = p.second.filename;
                string op = p.second.op;
                string proc = roundDouble(p.second.proc);

                if (p.second.op == "done")
                {
                    proc = "-";
                }

                std::cout << ERASE_LINE
                          << getFormatedString(id, printSpaces["id"])
                          << getFormatedString(time, printSpaces["time"])
                          << getFormatedString(filename, printSpaces["file"])
                          << getFormatedString(op, printSpaces["op"])
                          << getFormatedString(proc, printSpaces["status"], true)
                          << endl;

                writeLines++;
                cps++;
            }
            setLastRowCount(writeLines);
        }
    }

    int getMaxWidth()
    {
        if (!maxWidth)
        {
            maxWidth = accumulate(printSpaces.begin(), printSpaces.end(), 0.0, [](auto &sum, auto &item)
                                  { return sum + item.second; });

            maxWidth += printSpaces.size() - 1;
        }

        return maxWidth;
    }

    void printHeaderDashboard()
    {

        int tSize = getMaxWidth();

        cout << "\n";
        cout << getFormatedString(" Builder status ", tSize, true, '-') << endl;
        cout << getFormatedString("#id", printSpaces["id"])
             << getFormatedString("#time", printSpaces["time"])
             << getFormatedString("#file", printSpaces["file"])
             << getFormatedString("#op", printSpaces["op"])
             << getFormatedString("#status", printSpaces["status"], true)
             << endl;

        cout << string(tSize, '-') << endl;
    }

    size_t getLastRowCount() { return lastRowCount; }
    void setLastRowCount(size_t count) { lastRowCount = count; }

private:
    map<int, syncState> stateMap;

    future<void> printFuture;
    atomic<bool> printState = false;

    bool firstPass = true;

    uint64_t updateTime = 0;

    map<string, uint16_t> printSpaces = {{"id", 11}, {"time", 11}, {"file", 31}, {"op", 33}, {"status", 15}};

    pair<int, int> terminalSize;
    int maxWidth = 0;

    int lastRowCount = 0;
};

bool isPortAvailable(int port)
{
    // 1. Create a socket
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0)
    {
        std::cerr << "Error creating socket for pre-check: " << strerror(errno) << std::endl;
        return false;
    }

    // 2. Set SO_REUSEADDR
    // This allows us to re-bind to a port in TIME_WAIT state,
    // which mimics the behavior of most servers (including EzRpcServer).
    int optval = 1;
    setsockopt(sockfd, SOL_SOCKET, SO_REUSEADDR, &optval, sizeof(optval));

    // 3. Set up the address structure for *:port
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);       // Convert port to network byte order
    addr.sin_addr.s_addr = INADDR_ANY; // Bind to all interfaces (like "*:5999")

    // 4. Try to bind the socket
    int bind_result = bind(sockfd, (struct sockaddr *)&addr, sizeof(addr));

    // 5. CRITICAL: Close the socket immediately, no matter what.
    // This releases the port so our real server can use it.
    close(sockfd);

    if (bind_result < 0)
    {
        return false;
    }

    // Bind succeeded, the port is free.
    return true;
}